/**
 * Ties the merged Einstein-rec/Commerce-API shape to the rendered `ZimmProductCard` props, the
 * same doctrine `productInfo.test.ts` documents as "G1": every assertion below uses a value
 * unique to its own field (see `FULL` below — `id` is deliberately different from `productId`,
 * and the 'large' image group's `alt` is deliberately a value that must never be picked) so a
 * mapping that reads the wrong key fails rather than coincidentally matching.
 */
import { describe, expect, test, vi } from 'vitest';
import { selectRecentlyViewedCard, type FormatPrice, type RecentlyViewedProduct } from './recentlyViewedCard';

const formatPrice: FormatPrice = (amount, currency) => `${currency} ${amount.toFixed(2)}`;

// `id` is deliberately NOT equal to `productId` — a real matched rec always has them equal, but
// diverging them here means every test using FULL would fail loudly if the mapper ever read the
// wrong one (see RecentlyViewedProduct.productId's own comment on why productId is correct).
const FULL: RecentlyViewedProduct = {
  id: 'SDK-PRODUCT-ID-MUST-NOT-BE-USED',
  productId: 'REC-PRODUCT-ID-0001',
  name: 'Natura Mini Dress',
  price: 895,
  currency: 'AUD',
  imageGroups: [
    {
      viewType: 'medium',
      images: [
        {
          link: 'https://example.test/medium/natura-mini-dress-link.jpg',
          disBaseLink: 'https://cdn.example.test/medium/natura-mini-dress.jpg',
          alt: 'Natura Mini Dress, Ivory',
        },
      ],
    },
    {
      // Wrong viewType — must never be picked. If it is, this test's alt assertion fails.
      viewType: 'large',
      images: [
        { link: 'https://example.test/large/natura-mini-dress.jpg', alt: 'WRONG VIEWTYPE — MUST NOT BE PICKED' },
      ],
    },
  ],
  image: {
    disBaseLink: 'https://cdn.example.test/einstein/natura-mini-dress.jpg',
    alt: 'EINSTEIN FALLBACK — MUST NOT BE PICKED WHEN imageGroups HAS A USABLE MEDIUM IMAGE',
  },
};

describe('selectRecentlyViewedCard — happy path', () => {
  test('maps every field to its correct prop, preferring the medium imageGroups image over the flat Einstein fallback', () => {
    expect(selectRecentlyViewedCard(FULL, formatPrice)).toEqual({
      id: 'REC-PRODUCT-ID-0001',
      href: '/product/REC-PRODUCT-ID-0001',
      name: 'Natura Mini Dress',
      primaryImage: {
        src: 'https://cdn.example.test/medium/natura-mini-dress.jpg',
        alt: 'Natura Mini Dress, Ivory',
      },
      currentPrice: 'AUD 895.00',
    });
  });

  test('id and href are built from productId, not the SDK Product.id field', () => {
    const card = selectRecentlyViewedCard(FULL, formatPrice);
    expect(card?.id).toBe('REC-PRODUCT-ID-0001');
    expect(card?.id).not.toBe(FULL.id);
  });

  test('href is a bare /product/{id} path — no site-prefix of its own', () => {
    const card = selectRecentlyViewedCard(FULL, formatPrice);
    expect(card?.href).toBe('/product/REC-PRODUCT-ID-0001');
    expect(card?.href).not.toMatch(/^https?:\/\//);
  });

  test('omits headingLevel, variation, hoverImage and images entirely — not just empty', () => {
    const card = selectRecentlyViewedCard(FULL, formatPrice) as object | null;
    expect(card).not.toBeNull();
    expect(card).not.toHaveProperty('headingLevel');
    expect(card).not.toHaveProperty('variation');
    expect(card).not.toHaveProperty('hoverImage');
    expect(card).not.toHaveProperty('images');
  });
});

describe('selectRecentlyViewedCard — no usable name, no card', () => {
  test('returns null when name is missing', () => {
    expect(selectRecentlyViewedCard({ ...FULL, name: undefined }, formatPrice)).toBeNull();
  });

  test('returns null when name is an empty string', () => {
    expect(selectRecentlyViewedCard({ ...FULL, name: '' }, formatPrice)).toBeNull();
  });

  test('returns null for a nullish product (still loading)', () => {
    expect(selectRecentlyViewedCard(undefined, formatPrice)).toBeNull();
    expect(selectRecentlyViewedCard(null, formatPrice)).toBeNull();
  });
});

describe('selectRecentlyViewedCard — no usable image, no card', () => {
  // Decision (documented, not silently made): "no usable image at all" is treated the same as
  // "no usable name" — a hard null gate — rather than a placeholder-image card. A placeholder
  // would need an asset/src this codebase has no confirmed token for, and null is the only
  // choice that structurally cannot violate ZimmProductCardMediaImage.alt's required-non-empty
  // contract (there is no returned object for alt to be empty on). See selectPrimaryImage's own
  // docblock in recentlyViewedCard.ts for the same note at the point of the decision.
  test('returns null when imageGroups is absent and there is no fallback image either', () => {
    expect(selectRecentlyViewedCard({ ...FULL, imageGroups: undefined, image: undefined }, formatPrice)).toBeNull();
  });

  test('returns null when imageGroups is an empty array and there is no fallback image', () => {
    expect(selectRecentlyViewedCard({ ...FULL, imageGroups: [], image: undefined }, formatPrice)).toBeNull();
  });

  test('returns null when imageGroups filtering matches nothing (no medium viewType) and there is no fallback image', () => {
    const noMediumGroup: RecentlyViewedProduct = {
      ...FULL,
      imageGroups: [{ viewType: 'large', images: [{ link: 'https://example.test/large-only.jpg' }] }],
      image: undefined,
    };
    expect(selectRecentlyViewedCard(noMediumGroup, formatPrice)).toBeNull();
  });
});

describe('selectRecentlyViewedCard — fallback to the flat Einstein image field', () => {
  test('uses image.disBaseLink as the src when imageGroups is absent entirely', () => {
    const card = selectRecentlyViewedCard({ ...FULL, imageGroups: undefined }, formatPrice);
    expect(card?.primaryImage).toEqual({
      src: 'https://cdn.example.test/einstein/natura-mini-dress.jpg',
      alt: 'EINSTEIN FALLBACK — MUST NOT BE PICKED WHEN imageGroups HAS A USABLE MEDIUM IMAGE',
    });
  });

  test('falls back to the product name for alt when the flat image field carries no alt of its own', () => {
    const card = selectRecentlyViewedCard(
      { ...FULL, imageGroups: undefined, image: { disBaseLink: FULL.image?.disBaseLink, alt: undefined } },
      formatPrice,
    );
    expect(card?.primaryImage.alt).toBe('Natura Mini Dress');
  });
});

describe('selectRecentlyViewedCard — price without a paired currency (no guessed currency)', () => {
  test('currentPrice is undefined when currency is missing, and formatPrice is never called', () => {
    const spy = vi.fn(formatPrice);
    const card = selectRecentlyViewedCard({ ...FULL, currency: undefined }, spy);
    expect(card?.currentPrice).toBeUndefined();
    expect(spy).not.toHaveBeenCalled();
  });

  test('currentPrice is undefined when price is missing, and formatPrice is never called', () => {
    const spy = vi.fn(formatPrice);
    const card = selectRecentlyViewedCard({ ...FULL, price: undefined }, spy);
    expect(card?.currentPrice).toBeUndefined();
    expect(spy).not.toHaveBeenCalled();
  });

  test('calls the injected formatter exactly once, with the real price and currency, when both are present', () => {
    const spy = vi.fn(formatPrice);
    selectRecentlyViewedCard(FULL, spy);
    expect(spy).toHaveBeenCalledOnce();
    expect(spy).toHaveBeenCalledWith(895, 'AUD');
  });
});

